// Extract incident metadata safely and sanitize
const incident = items[0].json.body || items[0].json;

return [{
  json: {
    incident_id: incident.incident_id || incident.id,
    title: incident.title || 'IoT Security Anomaly Detected',
    severity: (incident.severity || 'HIGH').toUpperCase(),
    device_id: incident.device_id || 'unknown',
    confidence: incident.confidence ? `${(incident.confidence * 100).toFixed(0)}%` : '90%',
    observed_facts: incident.observed_facts || [],
    citations_count: (incident.citations || []).length,
    requires_human_approval: true,
    remediation_notice: 'No disruptive action will execute without operator approval in the EdgeShield Console.',
    timestamp: new Date().toISOString()
  }
}];

// Build operator dispatch notification
const alert = items[0].json;
console.log(`[EDGESHIELD DISPATCH] CRITICAL INCIDENT ${alert.incident_id} on ${alert.device_id}: ${alert.title}`);

return [{
  json: {
    status: 'dispatched',
    channel: 'operator_push_notification',
    alert: alert
  }
}];

// Routine notification log
const alert = items[0].json;
console.log(`[EDGESHIELD DISPATCH] HIGH INCIDENT ${alert.incident_id} on ${alert.device_id}`);
return [{ json: { status: 'logged', alert: alert } }];
